6	/// The Insertion Modal's 3 tabs — Boundaries: "3 equal-width tabs (Texto/
7	/// Áudio/Foto)". Only [texto] is functional this story; [audio]/[foto]
8	/// render idle, non-interactive placeholders (Stories 3.2/3.3).
9	enum CaptureTab { texto, audio, foto }
10	
11	/// Capture's own state for the Insertion Modal — never the shared
12	/// `Resource<T>` (Boundaries). A sealed class, not `freezed` (no codegen
13	/// for this story beyond `entry_dto.g.dart`, Verification): every
14	/// variant always carries the common [activeTab]/[text] so switching tabs
15	/// or typing never needs to know which variant it's coming from.
16	sealed class TextEntryState {
17	  const TextEntryState({required this.activeTab, required this.text});
18	
19	  final CaptureTab activeTab;
20	  final String text;
21	}
22	
23	/// Ready to type/save — the state immediately after the modal opens
24	/// (Boundaries: "Opens on Texto, all 3 tabs idle/empty"), after a tab
25	/// switch, and after a keystroke.
26	class TextEntryIdle extends TextEntryState {
27	  const TextEntryIdle({required super.activeTab, required super.text});
28	}
29	
30	/// Salvar tapped, `POST /entries` in flight — the I/O matrix's "no
31	/// auto-retry, no double-submit": `InsertionModal` disables Salvar/the
32	/// text field for the duration of this state.
33	class TextEntrySaving extends TextEntryState {
34	  const TextEntrySaving({required super.activeTab, required super.text});
35	}
36	
37	/// The save attempt succeeded — `InsertionModal`'s listener reacts to
38	/// this by popping the sheet (I/O matrix: "success closes the modal").
39	/// Terminal: nothing meaningful follows it for this cubit instance, since
40	/// the modal (and the factory-scoped cubit backing it) is already
41	/// closing.
42	class TextEntrySaved extends TextEntryState {
43	  const TextEntrySaved({required super.activeTab, required super.text});
44	}
45	
46	/// The last save attempt failed (incl. offline, via the existing
47	/// `Failure.networkOffline`) — [message] is `Failure.message` verbatim
48	/// (I/O matrix: "Inline message from `Failure.message`"); Salvar is
49	/// re-enabled, the modal stays open, no auto-retry.
50	class TextEntryError extends TextEntryState {
51	  const TextEntryError({
52	    required super.activeTab,
53	    required super.text,
54	    required this.message,
55	  });
56	
57	  final String message;
58	}
59	
60	/// Drives `InsertionModal`. Calls [EntriesRepository.create] directly on
61	/// [save] — no use-case layer, matching this codebase's existing
62	/// convention (Design Notes: `AccountSettingsCubit`/`AuthCubit`). A fresh,
63	/// `get_it`-factory-scoped instance per "+" tap (Boundaries: "Modal open
64	/// resets") — starting state is always [TextEntryIdle] on
65	/// [CaptureTab.texto] with empty text, so no explicit reset method is
66	/// needed the way `AccountSettingsCubit.clearStaleError()` needs one for
67	/// its own long-lived singleton.
68	class TextEntryCubit extends Cubit<TextEntryState> {
69	  TextEntryCubit(this._repository)
70	    : super(const TextEntryIdle(activeTab: CaptureTab.texto, text: ''));
71	
72	  final EntriesRepository _repository;
73	
74	  /// Switches the active tab, preserving whatever Texto text was already
75	  /// typed (Never: the full cross-tab cancel-safety rule is Story 3.4's
76	  /// scope — this story's trivial case just needs the tab itself to
77	  /// switch without losing in-progress text or firing any `create` call).
78	  /// Dropped while [TextEntrySaving]/[TextEntryError] is only cosmetic —
79	  /// a save already in flight for the Texto tab is untouched by this,
80	  /// since `save()` captures its own `activeTab`/`text` at call time.
81	  void selectTab(CaptureTab tab) {
82	    if (tab == state.activeTab) {
83	      return;
84	    }
85	    emit(TextEntryIdle(activeTab: tab, text: state.text));
86	  }
87	
88	  /// Mirrors the Texto field's own `TextEditingController` into this
89	  /// cubit's state, so [save] has the latest typed text to send. Ignored
90	  /// while a save is already in flight — the field is disabled in that
91	  /// state (`InsertionModal`), so this should never fire then regardless.
92	  void updateText(String text) {
93	    if (state is TextEntrySaving) {
94	      return;
95	    }
96	    emit(TextEntryIdle(activeTab: state.activeTab, text: text));
97	  }
98	
99	  /// I/O matrix's "Happy path save"/"Save fails" rows: fires `POST
100	  /// /entries` with `source: manual` (Boundaries — the only source this
101	  /// story ever sends) for whatever non-empty text is currently typed. A
102	  /// blank/whitespace-only text never calls [EntriesRepository.create] —
103	  /// `InsertionModal` already disables Salvar for that case, but this is
104	  /// the authoritative guard regardless of how `save()` is invoked.
105	  Future<void> save() async {
106	    final text = state.text.trim();
107	    if (text.isEmpty || state is TextEntrySaving) {
108	      return;
109	    }
110	    final activeTab = state.activeTab;
111	    emit(TextEntrySaving(activeTab: activeTab, text: text));
112	    final result = await _repository.create(
113	      content: text,
114	      source: EntrySource.manual,
115	    );
116	    // Mirrors `AccountSettingsCubit.toggleBiometric`'s own guard: this
117	    // cubit's `dispose:`/`close()` can race the awaited call above (e.g.
118	    // the modal's barrier is dismissed mid-save) — `emit()` after `close()`
119	    // would otherwise throw.
120	    if (isClosed) {
121	      return;
122	    }
123	    result.match(
124	      (failure) => emit(
125	        TextEntryError(activeTab: activeTab, text: text, message: failure.message),
126	      ),
127	      (_) => emit(TextEntrySaved(activeTab: activeTab, text: text)),
128	    );
129	  }
130	}
